/* Real project screenshots, paired with a reading-driven checklist. */
(() => {
 const img=(name,alt)=>`<img src="assets/seo/${name}.webp" alt="${alt}" loading="lazy">`;
 const tasks=[['research','竞品调研'],['keywords','追踪高频关键词'],['expert','专业人士视角'],['placement','关键词布局'],['pain','痛点开篇']];
 window.SEO_INSIGHT_HTML=`<div class="seo-insight-grid"><dl class="seo-brief">${[['项目背景','为 BC 雅思撰写 SEO 长文，回应留学人群在语言考试选择阶段产生的搜索需求。'],['目标受众','计划前往海外或港澳台留学、有语言要求的学生。'],['核心问题','如何通过竞品相关搜索内容，让 BC 雅思进入用户的考试选择范围？'],['写作目标','围绕不同语言考试及服务机构的差异布局关键词，为用户提供清晰、可信的比较信息，同时为 BC 雅思获取自然搜索流量。']].map(([k,v])=>`<div><dt>${k}</dt><dd>${v}</dd></div>`).join('')}</dl><div class="seo-search-scene"><span class="seo-desk-note handwritten">一次搜索，三个未解的问题。</span><form class="seo-search" aria-label="体验留学考试搜索"><span class="seo-query">雅思和 XX 怎么选<i class="seo-caret" aria-hidden="true"></i></span><button type="submit" aria-label="搜索雅思和其他考试如何选择"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6.5"/><path d="m15 15 6 6"/></svg></button></form><div class="seo-thoughts" aria-live="polite">${['哪项考试在留学认可度更高？','谁更容易出分？','哪家服务更好？'].map((s,i)=>`<p hidden style="--order:${i}">${s}</p>`).join('')}</div><span class="seo-search-invitation">点击搜索，看看问题背后的问题 ↗</span></div></div><div class="seo-core-insight"><span>THE OPPORTUNITY</span><p>用户搜索竞品，并不代表已经作出选择。</p><div>他们仍在收集信息、比较选择。认可度、出分难度和服务体验背后的多重焦虑，正是 BC 雅思通过专业比较内容进入决策过程的机会。</div></div><div class="seo-relationship"><span>客户 <b>BC 雅思</b></span><span>竞品 <b>托福 / 多邻国 / PTE / IDP 雅思</b></span></div>`;
 const sample=(key,n,title,file,alt,copy)=>`<article class="seo-material seo-sample" data-seo-task="${key}"><div class="seo-material-heading"><span>03.${n} / WRITING NOTES</span><h3>${title}</h3></div><figure class="seo-paper seo-crop"><i class="seo-pin" aria-hidden="true"></i>${img(file,alt)}<i class="seo-pencil-line" aria-hidden="true"></i></figure><p>${copy}</p></article>`;
 window.SEO_STRATEGY_HTML=`<p class="seo-strategy-lead">把搜索需求，整理成一篇有依据、有重点的比较文章。</p><div class="seo-research-desk"><aside class="seo-folder" aria-label="SEO 写作进度"><div class="seo-folder-tab">BC IELTS / SEO</div><div class="seo-folder-sheet"><div class="seo-folder-heading"><span>CHECKING LIST</span><span class="seo-progress" role="status" aria-live="polite">0 / 5</span></div><p class="handwritten">写之前，先把问题理清。</p><ol class="seo-checks">${tasks.map(([key,title],i)=>`${i===2?'<li class="seo-check-group">03　写作要点</li>':''}<li class="${i>1?'seo-subtask':''}" data-seo-check="${key}"><span class="seo-check-box" aria-hidden="true"><svg viewBox="0 0 36 32"><path d="m4 16 9 10L32 4"/></svg></span><span>${i<2?`0${i+1}　`:''}${title}</span><span class="seo-check-status">待阅读</span></li>`).join('')}</ol><div class="seo-folder-bottom"><span>RESEARCH → KEYWORDS → COPY</span><b class="seo-done-stamp" aria-hidden="true">READY TO WRITE</b></div></div><i class="seo-folder-clip" aria-hidden="true"></i></aside><div class="seo-materials"><article class="seo-material" data-seo-task="research"><div class="seo-material-heading"><span>01 / COMPETITOR RESEARCH</span><h3>竞品调研</h3></div><div class="seo-research-board"><figure class="seo-paper">${img('research-overview','原项目调研截图：竞品对比、寻找己方用户利益点与共享话术整理')}</figure><span class="seo-research-tag seo-tag-a">认可度</span><span class="seo-research-tag seo-tag-b">考试设置</span><span class="seo-research-tag seo-tag-c">服务体验</span></div><p>比较考试与服务机构的差异，从资料中寻找能回应用户疑问的利益点，再把可复用表达积累进共享话术库。</p><details class="seo-table-detail"><summary>展开原始调研表 ↗</summary><div class="seo-table-scroll" tabindex="0" role="region" aria-label="原始调研表，可横向滚动">${img('research-table','原项目 BC 雅思与 IDP 雅思调研表，包含认可度、考试设置等比较维度')}</div></details></article><article class="seo-material" data-seo-task="keywords"><div class="seo-material-heading"><span>02 / KEYWORD TRACKING</span><h3>追踪高频关键词</h3></div><figure class="seo-paper seo-keyword-paper"><i class="seo-paper-tape" aria-hidden="true"></i><div class="seo-table-scroll" tabindex="0" role="region" aria-label="关键词工作表，可横向滚动">${img('keywords','关键词工作截图：留学相关搜索词、月均搜索指数及市场出价')}</div></figure><p>结合搜索词和搜索指数理解用户关心的问题，围绕考试及服务机构的差异组织核心词与长尾词。</p><div class="seo-keyword-note"><span class="handwritten">从搜索词，走近真实需求 ↗</span><small>原项目关键词工作材料</small></div></article>${sample('expert','1','专业人士视角','sample-expert','真实文章局部截图：以留学行业深度观察员身份开篇','以留学行业观察者的视角进入话题，交代观察范围与专业立场，让比较信息有清晰的叙述者。')}${sample('placement','2','关键词布局','sample-keyword','同一篇真实文章标题截图：BC 和 IDP 差异在哪、BC 与 IDP 的本质分野等比较关键词','把“BC 和 IDP 差异在哪”等核心疑问放进标题，同时用相关长尾表达承接不同的搜索方式。')}${sample('pain','3','痛点开篇','sample-pain','同一篇真实文章开篇局部截图：留学流向变化、留学与就业路径的决策语境','从留学环境变化切入，把考试选择放回申请与就业的现实语境，回应读者当下的决策焦虑。')}<div class="seo-desk-finish"><span class="handwritten">从资料桌，到读者的选择里。</span><p>用专业比较承接搜索，让 BC 雅思进入尚未完成的考试决策。</p><a href="index.html#writing-seo" class="inline-link">返回 SEO 文案 ↩</a></div></div></div>`;
 document.addEventListener('DOMContentLoaded',()=>{
  if(new URLSearchParams(location.search).get('project')!=='seo')return;
  document.body.classList.add('seo-page');
  const scene=document.querySelector('.seo-search-scene');
  document.querySelector('.seo-search').addEventListener('submit',e=>{e.preventDefault();if(scene.classList.contains('is-searched'))return;scene.querySelectorAll('.seo-thoughts p').forEach(p=>p.hidden=false);requestAnimationFrame(()=>scene.classList.add('is-searched'));scene.querySelector('.seo-search-invitation').textContent='每一个疑问，都是进入决策的机会。';});
  const completed=new Set(),checks=[...document.querySelectorAll('[data-seo-check]')];
  const observer=new IntersectionObserver(entries=>entries.forEach(e=>{if(!e.isIntersecting)return;const key=e.target.closest('[data-seo-task]').dataset.seoTask;if(!completed.has(key)){completed.add(key);const check=checks.find(c=>c.dataset.seoCheck===key);check.classList.add('is-checked');check.querySelector('.seo-check-status').textContent='已阅读';document.querySelector('.seo-progress').textContent=`${completed.size} / 5`;if(completed.size===5)document.querySelector('.seo-folder').classList.add('is-complete');}observer.unobserve(e.target);}),{rootMargin:'-34% 0px -16% 0px',threshold:0});
  document.querySelectorAll('[data-seo-task] .seo-paper').forEach(el=>observer.observe(el));
  const chapter=document.querySelector('#chapter-2');let queued=false;
  const sync=()=>{document.documentElement.classList.toggle('seo-reading-strategy',chapter.getBoundingClientRect().top<innerHeight*.65);queued=false;};
  addEventListener('scroll',()=>{if(!queued){queued=true;requestAnimationFrame(sync);}},{passive:true});addEventListener('resize',sync);sync();
 });
})();
